/// <summary>
/// AVA/WEN/2024/11/14      AVA_012732_AddCustomerTorCreditLimitGroup
/// </summary>
/// <param name = "_company">DataAreaId</param>
/// <param name = "_custAccount">CustAccount</param>
/// <returns>boolean</returns>
public static boolean avaCustCompanyGuaranteeExists(DataAreaId _company, CustAccount _custAccount)
{
    CredManCustGuaranteeInsurance  guarantee;

    changecompany(_company)
    {
        select firstonly guarantee
                where guarantee.DataAreaId == _company
        && guarantee.CustAccount == _custAccount;
    }
    return guarantee.RecId;
}
